import { gradeVoxels } from './solution';
import type { VoxelGrid, Grade } from './solution';

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}
function deepEqual(actual: unknown, expected: unknown, message: string): void {
  if (JSON.stringify(actual) !== JSON.stringify(expected)) throw new Error(message);
}
function expectRange(fn: () => unknown, message: string): void {
  let error: unknown;
  try { fn(); } catch (caught) { error = caught; }
  assert(error instanceof RangeError, message);
}

const colors = [
  { r: 10, g: 100, b: 250 },
  { r: -5, g: 0.25, b: 100 }
];
const grid: VoxelGrid = { width: 2, height: 1, depth: 1, colors };
const grade: Grade = {
  gain: { r: 2, g: -1, b: 2 },
  offset: { r: 0.4, g: 300, b: -10 }
};
const gridBefore = JSON.stringify(grid);
const gradeBefore = JSON.stringify(grade);
const result = gradeVoxels(grid, grade);
deepEqual(result, {
  width: 2,
  height: 1,
  depth: 1,
  colors: [
    { r: 20, g: 200, b: 255 },
    { r: 0, g: 255, b: 190 }
  ]
}, 'channels are graded, clamped, rounded, and kept in flat order');
assert(JSON.stringify(grid) === gridBefore, 'grid is not mutated');
assert(JSON.stringify(grade) === gradeBefore, 'grade is not mutated');
assert(result !== grid, 'result grid is new');
assert(result.colors !== grid.colors, 'result color array is new');
assert(result.colors[0] !== grid.colors[0], 'result colors are new objects');
colors[0].r = 99;
equalColor(result.colors[0], { r: 20, g: 200, b: 255 }, 'result does not alias input colors');

function equalColor(actual: { readonly r: number; readonly g: number; readonly b: number }, expected: { r: number; g: number; b: number }, message: string): void {
  deepEqual(actual, expected, message);
}

const emptyColors: Array<{ r: number; g: number; b: number }> = [];
const emptyGrid: VoxelGrid = { width: 0, height: 4, depth: 3, colors: emptyColors };
const emptyResult = gradeVoxels(emptyGrid, { gain: { r: 1, g: 1, b: 1 }, offset: { r: 0, g: 0, b: 0 } });
deepEqual(emptyResult, { width: 0, height: 4, depth: 3, colors: [] }, 'zero-volume grid is supported');
assert(emptyResult !== emptyGrid && emptyResult.colors !== emptyColors, 'empty result is fully newly allocated');

const validGrade: Grade = { gain: { r: 1, g: 1, b: 1 }, offset: { r: 0, g: 0, b: 0 } };
expectRange(() => gradeVoxels({ width: -1, height: 1, depth: 1, colors: [] }, validGrade), 'negative dimension is rejected');
expectRange(() => gradeVoxels({ width: 1.5, height: 1, depth: 1, colors: [] }, validGrade), 'fractional dimension is rejected');
expectRange(() => gradeVoxels({ width: 1, height: 1, depth: 1, colors: [] }, validGrade), 'color count mismatch is rejected');
expectRange(() => gradeVoxels({ width: 0, height: 1, depth: 1, colors: [{ r: 0, g: 0, b: 0 }] }, validGrade), 'nonempty zero-volume grid is rejected');
expectRange(() => gradeVoxels({ width: 1, height: 1, depth: 1, colors: [{ r: NaN, g: 0, b: 0 }] }, validGrade), 'non-finite input channel is rejected');
expectRange(() => gradeVoxels({ width: 0, height: 0, depth: 0, colors: [] }, { gain: { r: Infinity, g: 1, b: 1 }, offset: { r: 0, g: 0, b: 0 } }), 'grade channels are validated for empty grids');
expectRange(() => gradeVoxels({ width: Number.MAX_SAFE_INTEGER, height: 2, depth: 1, colors: [] }, validGrade), 'unsafe dimension product is rejected');

